import { useEffect, useMemo, useState } from "react";
import { ApiClient, ApiError } from "./api";
import { LoginPage } from "./LoginPage";
import {
  clearSession,
  isExpired,
  readPersistedSession,
  takeExpirationNotice,
} from "./session";

const SESSION_EXPIRED_MESSAGE = "Tu sesión expiró, ingresá nuevamente";
const CONNECTION_MESSAGE = "No se pudo conectar, reintentá";

interface AppProps {
  apiBaseUrl?: string;
  navigate?: (path: string) => void;
}

function defaultNavigate(path: string): void {
  window.location.assign(path);
}

export function App({
  apiBaseUrl = import.meta.env.VITE_API_BASE_URL ?? "http://localhost:3000",
  navigate = defaultNavigate,
}: AppProps) {
  const [checkingSession, setCheckingSession] = useState(true);
  const [notice, setNotice] = useState<string | null>(() =>
    takeExpirationNotice() ? SESSION_EXPIRED_MESSAGE : null,
  );
  const api = useMemo(
    () =>
      new ApiClient({
        baseUrl: apiBaseUrl,
        onUnauthenticated: () => navigate("/login"),
      }),
    [apiBaseUrl, navigate],
  );

  useEffect(() => {
    let active = true;
    const persisted = readPersistedSession();

    if (persisted === null || isExpired(persisted)) {
      clearSession();
      setCheckingSession(false);
      return () => {
        active = false;
      };
    }

    void api.profile(persisted.token).then(
      () => {
        if (active) navigate("/trading");
      },
      (error: unknown) => {
        if (!active) return;
        if (error instanceof ApiError && error.code === "UNAUTHENTICATED") {
          clearSession();
        } else {
          setNotice(CONNECTION_MESSAGE);
        }
        setCheckingSession(false);
      },
    );

    return () => {
      active = false;
    };
  }, [api, navigate]);

  if (checkingSession) {
    return (
      <main className="session-check" aria-live="polite">
        <div className="spinner" aria-hidden="true" />
        <p>Validando tu sesión…</p>
      </main>
    );
  }

  return (
    <LoginPage
      api={api}
      initialNotice={notice}
      onAuthenticated={() => navigate("/trading")}
    />
  );
}

