import { useEffect, useRef, useState, type FormEvent } from "react";
import {
  ApiClient,
  ApiError,
  NetworkError,
  validationIssues,
  type ValidationIssue,
} from "./api";
import { saveSession } from "./session";

const INVALID_CREDENTIALS_MESSAGE = "Email o contraseña incorrectos";
const CONNECTION_MESSAGE = "No se pudo conectar, reintentá";

interface LoginPageProps {
  api: ApiClient;
  onAuthenticated: () => void;
  initialNotice?: string | null;
}

function issuesByField(issues: ValidationIssue[]): Map<string, string[]> {
  const grouped = new Map<string, string[]>();
  for (const issue of issues) {
    const existing = grouped.get(issue.field) ?? [];
    existing.push(issue.message);
    grouped.set(issue.field, existing);
  }
  return grouped;
}

export function LoginPage({ api, onAuthenticated, initialNotice = null }: LoginPageProps) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [notice, setNotice] = useState<string | null>(initialNotice);
  const [issues, setIssues] = useState<ValidationIssue[]>([]);
  const [retrySeconds, setRetrySeconds] = useState(0);
  const [retryDeadline, setRetryDeadline] = useState<number | null>(null);
  const requestInFlight = useRef(false);

  useEffect(() => {
    if (retryDeadline === null) return;
    const updateCountdown = () => {
      const remaining = Math.max(0, Math.ceil((retryDeadline - Date.now()) / 1_000));
      setRetrySeconds(remaining);
      if (remaining === 0) setRetryDeadline(null);
    };
    const timer = window.setInterval(updateCountdown, 250);
    return () => window.clearInterval(timer);
  }, [retryDeadline]);

  const errors = issuesByField(issues);
  const emailErrors = errors.get("email") ?? [];
  const passwordErrors = errors.get("password") ?? [];
  const formErrors = [
    ...(errors.get("form") ?? []),
    ...(errors.get("body") ?? []),
  ];
  const disabled = email.length === 0 || password.length === 0 || submitting || retrySeconds > 0;

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (requestInFlight.current || disabled) return;

    requestInFlight.current = true;
    setSubmitting(true);
    setNotice(null);
    setIssues([]);

    try {
      const session = await api.login(email, password);
      saveSession(session);
      onAuthenticated();
    } catch (error) {
      if (error instanceof ApiError && error.code === "INVALID_CREDENTIALS") {
        setNotice(INVALID_CREDENTIALS_MESSAGE);
        setPassword("");
      } else if (error instanceof ApiError && error.code === "VALIDATION_ERROR") {
        const parsedIssues = validationIssues(error);
        setIssues(
          parsedIssues.length > 0
            ? parsedIssues
            : [{ field: "form", message: "Revisá los datos ingresados" }],
        );
      } else if (error instanceof ApiError && error.code === "RATE_LIMITED") {
        const wait = error.details?.retryAfterSeconds;
        const seconds = typeof wait === "number" && Number.isInteger(wait) && wait >= 0 ? wait : 1;
        setRetrySeconds(seconds);
        setRetryDeadline(Date.now() + seconds * 1_000);
      } else if (
        error instanceof NetworkError ||
        (error instanceof ApiError && error.code === "INTERNAL_ERROR")
      ) {
        setNotice(CONNECTION_MESSAGE);
      } else {
        setNotice(CONNECTION_MESSAGE);
      }
    } finally {
      requestInFlight.current = false;
      setSubmitting(false);
    }
  }

  return (
    <main className="login-shell">
      <section className="brand-panel" aria-label="Información del mercado">
        <a className="brand" href="/login" aria-label="Orbe Exchange, inicio">
          <span className="brand-mark" aria-hidden="true">O</span>
          <span>ORBE</span>
        </a>
        <div className="market-copy">
          <p className="eyebrow">EXCHANGE · SEPOLIA</p>
          <h1>Un acceso claro.<br />Un mercado sin ruido.</h1>
          <p className="intro">
            Entrá a tu cuenta para operar el par ETH/USDC en el entorno de pruebas.
          </p>
        </div>
        <div className="pair-card" aria-label="Mercado disponible">
          <div className="asset-stack" aria-hidden="true">
            <span className="asset eth">Ξ</span>
            <span className="asset usdc">$</span>
          </div>
          <div>
            <span className="pair-label">Mercado disponible</span>
            <strong>ETH/USDC</strong>
          </div>
          <span className="network-dot">Sepolia</span>
        </div>
        <p className="environment-note">Los activos de testnet no tienen valor económico real.</p>
      </section>

      <section className="form-panel">
        <div className="login-card">
          <p className="eyebrow">BIENVENIDO</p>
          <h2>Ingresá a tu cuenta</h2>
          <p className="form-intro">Usá las credenciales con las que te registraste.</p>

          {notice && <div className="notice" role="alert">{notice}</div>}
          {retrySeconds > 0 && (
            <div className="notice notice-rate" role="status" aria-live="polite">
              Demasiados intentos. Intentá nuevamente en {retrySeconds} {retrySeconds === 1 ? "segundo" : "segundos"}.
            </div>
          )}
          {formErrors.length > 0 && (
            <div className="notice" role="alert">
              {formErrors.map((message, index) => <p key={`${message}-${index}`}>{message}</p>)}
            </div>
          )}

          <form noValidate onSubmit={submit}>
            <div className="field">
              <label htmlFor="email">Email</label>
              <input
                id="email"
                name="email"
                type="text"
                inputMode="email"
                autoComplete="username"
                value={email}
                onChange={(event) => setEmail(event.target.value)}
                aria-invalid={emailErrors.length > 0}
                aria-describedby={emailErrors.length > 0 ? "email-errors" : undefined}
                required
              />
              {emailErrors.length > 0 && (
                <div id="email-errors" className="field-error" role="alert">
                  {emailErrors.map((message, index) => <p key={`${message}-${index}`}>{message}</p>)}
                </div>
              )}
            </div>

            <div className="field">
              <label htmlFor="password">Contraseña</label>
              <input
                id="password"
                name="password"
                type="password"
                autoComplete="current-password"
                value={password}
                onChange={(event) => setPassword(event.target.value)}
                aria-invalid={passwordErrors.length > 0}
                aria-describedby={passwordErrors.length > 0 ? "password-errors" : undefined}
                required
              />
              {passwordErrors.length > 0 && (
                <div id="password-errors" className="field-error" role="alert">
                  {passwordErrors.map((message, index) => <p key={`${message}-${index}`}>{message}</p>)}
                </div>
