      "/api/v1/me",
      { headers: { Authorization: `Bearer ${token}` } },
      true,
    );
    return payload as ProfileResponse;
  }

  async protectedRequest(path: string, token: string, init: RequestInit = {}): Promise<unknown> {
    const headers = new Headers(init.headers);
    headers.set("Authorization", `Bearer ${token}`);
    return this.request(path, { ...init, headers }, true);
  }

  private async request(path: string, init: RequestInit, protectedCall = false): Promise<unknown> {
    let response: Response;
    try {
      response = await this.fetchImpl(`${this.baseUrl}${path}`, init);
    } catch {
      throw new NetworkError();
    }

    const payload = await responsePayload(response);
    if (response.ok) return payload;

    const apiError = parseApiError(payload) ?? new NetworkError();
    if (protectedCall && apiError instanceof ApiError && apiError.code === "UNAUTHENTICATED") {
      clearSession();
      markExpirationNotice();
      this.onUnauthenticated();
    }
    throw apiError;
  }
}

export function validationIssues(error: ApiError): ValidationIssue[] {
  const raw = error.details?.issues;
  if (!Array.isArray(raw)) return [];

  return raw.flatMap((item): ValidationIssue[] => {
    if (typeof item === "string") return [{ field: "form", message: item }];
    if (typeof item !== "object" || item === null) return [];
    const candidate = item as Record<string, unknown>;
    const fieldValue = candidate.field ?? candidate.path;
    const messageValue = candidate.message;
    const path = Array.isArray(fieldValue)
      ? fieldValue.filter((part): part is string => typeof part === "string").at(-1)
      : fieldValue;
    const leaf = typeof path === "string" ? path.split(/[/.]/).filter(Boolean).at(-1) : undefined;
    const field = leaf === "email" || leaf === "password" || leaf === "body" ? leaf : "form";
    return typeof messageValue === "string" && messageValue.length > 0
      ? [{ field, message: messageValue }]
      : [];
  });
}

