import { AppError } from "../errors.js";
import type { WalletService } from "../wallet/service.js";
import {
  generateOpaqueToken,
  hashOpaqueToken,
  hashPassword,
  isValidEmail,
  normalizeEmail,
  verifyPassword,
} from "./crypto.js";

export interface AccountView {
  accountId: string;
  email: string;
  status: "ACTIVE";
  createdAt: string;
}

interface AccountCredentialRow {
  account_id: string;
  email: string;
  password_hash: string;
  status: "ACTIVE";
  created_at: string;
}

interface SessionRow {
  account_id: string;
  expires_at: string;
}

export interface AuthenticatedSession {
  accountId: string;
  expiresAt: string;
}

export class AuthService {
  constructor(
    private readonly db: Database,
    private readonly wallet: WalletService,
    private readonly ttlSeconds: number,
    private readonly now: () => Date = () => new Date(),
  ) {}

  async register(emailInput: string, password: string): Promise<AccountView> {
    const email = normalizeEmail(emailInput);
    if (!isValidEmail(email)) {
      throw new AppError("VALIDATION_ERROR", "El email no tiene un formato válido.", {
        issues: [{ field: "email", message: "Formato o longitud inválidos" }],
      });
    }
    const passwordLength = Array.from(password).length;
    if (passwordLength < 8 || passwordLength > 128) {
      throw new AppError("VALIDATION_ERROR", "La contraseña no cumple la longitud requerida.", {
        issues: [{ field: "password", message: "Debe tener entre 8 y 128 caracteres" }],
      });
    }

    // The intentionally expensive KDF stays outside the short write transaction.
    const passwordHash = await hashPassword(password);
    const account: AccountView = {
      accountId: randomUUID(),
      email,
      status: "ACTIVE",
      createdAt: this.now().toISOString(),
    };

    try {
      immediateTransaction(this.db, () => {
        this.db.prepare(`
          INSERT INTO accounts (
            account_id, email, password_hash, status, created_at,
            eth_available, eth_locked, usdc_available, usdc_locked
          ) VALUES (?, ?, ?, 'ACTIVE', ?, '0', '0', '0', '0')
        `).run(account.accountId, account.email, passwordHash, account.createdAt);
        // Eager and atomic: an externally visible account never exists without its address.
        this.wallet.assignWithinTransaction(account.accountId);
      });
    } catch (error) {
      if (isUniqueEmailError(error)) {
        throw new AppError("EMAIL_ALREADY_EXISTS", "Ya existe una cuenta con ese email.", {
          email,
        });
      }
      throw error;
    }

    return account;
  }

  async login(
    emailInput: string,
    password: string,
    origin: string,
  ): Promise<{ token: string; expiresAt: string } | null> {
    const email = normalizeEmail(emailInput);
    const row = this.db
      .prepare("SELECT account_id, email, password_hash, status, created_at FROM accounts WHERE email = ?")
      .get(email) as unknown as AccountCredentialRow | undefined;

    const valid = await verifyPassword(password, row?.password_hash);
    if (!row || !valid || row.status !== "ACTIVE") {
      this.writeAudit(email, "FAILURE", "INVALID_CREDENTIALS", origin);
      return null;
    }

    const token = generateOpaqueToken();
    const expiresAt = new Date(this.now().getTime() + this.ttlSeconds * 1_000).toISOString();
    this.db
      .prepare("INSERT INTO sessions (token_hash, account_id, expires_at) VALUES (?, ?, ?)")
      .run(hashOpaqueToken(token), row.account_id, expiresAt);
    this.writeAudit(email, "SUCCESS", null, origin);
    return { token, expiresAt };
  }

  authenticate(authorization: string | undefined): string {
    return this.authenticateSession(authorization).accountId;
  }

  authenticateSession(authorization: string | undefined): AuthenticatedSession {
    const tokenHash = presentedTokenHash(authorization);
    const row = this.db
      .prepare("SELECT account_id, expires_at FROM sessions WHERE token_hash = ?")
      .get(tokenHash) as unknown as SessionRow | undefined;
    if (!row || Date.parse(row.expires_at) <= this.now().getTime()) throw unauthenticated();
    return { accountId: row.account_id, expiresAt: row.expires_at };
  }

  /**
   * Atomically revoke exactly the opaque session presented by the caller.
   *
   * The conditional DELETE is both the validity check and the durable state change. This
   * gives concurrent requests compare-and-swap semantics: only the request that deletes
   * the still-active row succeeds; every later/repeated request observes no active row.
   */
  logout(authorization: string | undefined): void {
    const tokenHash = presentedTokenHash(authorization);
    const result = this.db
      .prepare("DELETE FROM sessions WHERE token_hash = ? AND expires_at > ?")
      .run(tokenHash, this.now().toISOString());
    if (result.changes !== 1) throw unauthenticated();
  }

  getAccount(accountId: string): AccountView {
    const row = this.db
      .prepare("SELECT account_id, email, status, created_at FROM accounts WHERE account_id = ?")
      .get(accountId) as unknown as Omit<AccountCredentialRow, "password_hash"> | undefined;

