60→  const limits = options.rateLimits ?? new RateLimitService();
  const app = Fastify({ logger: false, exposeHeadRoutes: false });
  await app.register(fastifyWebsocket, { options: { maxPayload: 64 * 1024 } });
  const loginPrechecks = new WeakMap<FastifyRequest, RateLimitDecision>();

