    sendCorsPreflight(request, reply, "GET"),
  );

  app.post(
    "/api/v1/auth/register",
    { onRequest: async (request, reply) => enforceLimit(reply, limits.consumeRegister(request.ip)) },
    async (request, reply) => {
170→      const body = parseRegisterBody(parseJsonRequestBody(request));
      const account = await auth.register(body.email, body.password);
      return reply.code(201).send(account);
    },
  );

  app.post(
    "/api/v1/auth/login",
    {
      onRequest: async (request) => {
180→        const precheck = limits.precheckLogin(request.ip);
        loginPrechecks.set(request, precheck);
      },
    },
    async (request, reply) => {
      const precheck = loginPrechecks.get(request)!;
      if (!precheck.allowed) {
        const email = bestEffortEmail(request.body);
        auth.writeAudit(email, "FAILURE", "RATE_LIMITED", request.ip);
        enforceLimit(reply, precheck);
190→        return;
      }
      let body: { email: string; password: string };
      try {
        body = parseLoginBody(parseJsonRequestBody(request));
      } catch (error) {
        const raw = bestEffortEmail(request.body);
        auth.writeAudit(raw, "FAILURE", "VALIDATION_ERROR", request.ip);
        limits.recordLoginFailure(request.ip);
        throw error;
200→      }

