import Fastify, { type FastifyInstance, type FastifyReply, type FastifyRequest } from "fastify";
import fastifyWebsocket from "@fastify/websocket";
import type { Config } from "./config.js";
import { CHAIN_ID } from "./config.js";
import { openDatabase, type Database } from "./database.js";
import { AppError, errorBody, validationIssue } from "./errors.js";
import { RateLimitService, type RateLimitDecision } from "./rate-limit.js";
import { verifyRpcChain } from "./rpc.js";
import { AuthService } from "./auth/service.js";
import { normalizeEmail } from "./auth/crypto.js";
import { WalletService } from "./wallet/service.js";
import { attachWebSocketSession } from "./websocket.js";

interface ApplicationOptions {
  db?: Database;
  now?: () => Date;
  rateLimits?: RateLimitService;
  verifyRpc?: boolean;
  wsAuthTimeoutMs?: number;
  wsHeartbeatIntervalMs?: number;
  wsPongTimeoutMs?: number;
}

export interface Application {
  app: FastifyInstance;
  db: Database;
  auth: AuthService;
  wallet: WalletService;
}

const KNOWN_ROUTES = new Map<string, string[]>([
  ["/health", ["GET"]],
  ["/api/v1/auth/register", ["POST"]],
  ["/api/v1/auth/login", ["POST"]],
  ["/api/v1/auth/logout", ["POST"]],
  ["/api/v1/me", ["GET"]],
  ["/api/v1/deposit-address", ["GET"]],
]);

export async function createApplication(
  config: Config,
  options: ApplicationOptions = {},
): Promise<Application> {
  if (options.verifyRpc !== false) await verifyRpcChain(config.rpcUrl);
  const ownsDatabase = options.db === undefined;
  const db = options.db ?? openDatabase(config.databasePath);
  let wallet: WalletService;
  try {
    wallet = WalletService.provision(
      db,
      config.walletEncryptionKey,
      config.walletMnemonic,
      config.walletPassphrase,
    );
  } catch (error) {
    if (ownsDatabase) db.close();
    throw error;
  }
  const auth = new AuthService(db, wallet, config.sessionTtlSeconds, options.now);
  const limits = options.rateLimits ?? new RateLimitService();
  const app = Fastify({ logger: false, exposeHeadRoutes: false });
  await app.register(fastifyWebsocket, { options: { maxPayload: 64 * 1024 } });
  const loginPrechecks = new WeakMap<FastifyRequest, RateLimitDecision>();

  // The React client is served from a different origin during development and in a
  // typical deployment. Authentication uses an explicit Bearer header (never cookies),
  // so a wildcard origin is safe here while the requested headers must be explicit for
  // browser preflight checks.
  app.addHook("onRequest", (_request, reply, done) => {
    reply.header("Access-Control-Allow-Origin", "*");
    reply.header("Access-Control-Allow-Methods", "GET, POST, DELETE, OPTIONS");
    reply.header("Access-Control-Allow-Headers", "Authorization, Content-Type");
    reply.header("Access-Control-Max-Age", "600");
    done();
  });

  // Keep parsing after the onRequest rate-limit step. This preserves the required
  // rate-limit > schema precedence while still allowing every failed login to be audited.
  app.removeContentTypeParser("application/json");
  app.addContentTypeParser("application/json", { parseAs: "string" }, (_request, body, done) => {
    done(null, body);
  });
  app.addContentTypeParser("*", { parseAs: "string" }, (_request, body, done) => {
    done(null, body);
  });

  if (ownsDatabase) {
    app.addHook("onClose", async () => db.close());
  }

  app.setErrorHandler((cause, request, reply) => {
    let error: AppError;
    if (cause instanceof AppError) {
      error = cause;
    } else if (isBodyTooLargeError(cause)) {
      const routingError = requestRoutingError(request);
      if (routingError) return sendRoutingError(reply, routingError);

      if (request.method === "POST" && requestPath(request) === "/api/v1/auth/login") {
        const precheck = loginPrechecks.get(request) ?? limits.precheckLogin(request.ip);
        if (!precheck.allowed) {
          // Fastify does not expose a body after rejecting its stream, so the attempt
          // cannot be attributed to a trustworthy normalized email.
          auth.writeAudit("", "FAILURE", "RATE_LIMITED", request.ip);
          return enforceLimit(reply, precheck);
        }
        // A body rejected by Fastify never reaches the login handler. It is still a
        // failed authentication attempt for rate-limit and audit purposes. Since the
        // rejected stream is unavailable, no purported email can be trusted/extracted.
        auth.writeAudit("", "FAILURE", "VALIDATION_ERROR", request.ip);
        limits.recordLoginFailure(request.ip);
      } else if (
        request.method === "GET" &&
        requestPath(request) === "/api/v1/deposit-address"
      ) {
        // Authentication and the per-account limit precede input validation on protected
        // resources, including validation performed after a parser-size rejection.
        let accountId: string;
        try {
          accountId = auth.authenticate(request.headers.authorization);
        } catch (authenticationError) {
          if (authenticationError instanceof AppError) {
            return sendAppError(reply, authenticationError);
          }
          return sendAppError(reply, new AppError("INTERNAL_ERROR", "Ocurrió un error interno."));
        }
        const decision = limits.consumeProtected(accountId, "/api/v1/deposit-address");
        if (!decision.allowed) return enforceLimit(reply, decision);
      }

      error = validationIssue("body", "El cuerpo excede el tamaño permitido");
    } else if (isFrameworkValidationError(cause)) {
      error = validationIssue("body", "El cuerpo debe ser JSON válido con Content-Type application/json");
    } else {
      error = new AppError("INTERNAL_ERROR", "Ocurrió un error interno.");
    }
    sendAppError(reply, error);
  });

  app.setNotFoundHandler((request, reply) => {
    const routingError = requestRoutingError(request);
    return sendRoutingError(
      reply,
      routingError ?? new AppError("NOT_FOUND", "El recurso solicitado no existe."),
    );
  });

  app.get("/health", async () => ({ status: "ok" }));

  app.get("/api/v1/ws", { websocket: true }, (socket) => {
    attachWebSocketSession(socket, auth, {
      authTimeoutMs: options.wsAuthTimeoutMs,
      heartbeatIntervalMs: options.wsHeartbeatIntervalMs,
      pongTimeoutMs: options.wsPongTimeoutMs,
      now: options.now,
    });
  });

  app.options("/api/v1/auth/login", async (request, reply) =>
    sendCorsPreflight(request, reply, "POST"),
  );
  app.options("/api/v1/me", async (request, reply) =>
    sendCorsPreflight(request, reply, "GET"),
  );

  app.post(
    "/api/v1/auth/register",
    { onRequest: async (request, reply) => enforceLimit(reply, limits.consumeRegister(request.ip)) },
    async (request, reply) => {
      const body = parseRegisterBody(parseJsonRequestBody(request));
      const account = await auth.register(body.email, body.password);
      return reply.code(201).send(account);
    },
  );

  app.post(
    "/api/v1/auth/login",
    {
      onRequest: async (request) => {
        const precheck = limits.precheckLogin(request.ip);
        loginPrechecks.set(request, precheck);
      },
    },
    async (request, reply) => {
      const precheck = loginPrechecks.get(request)!;
      if (!precheck.allowed) {
        const email = bestEffortEmail(request.body);
        auth.writeAudit(email, "FAILURE", "RATE_LIMITED", request.ip);
        enforceLimit(reply, precheck);
        return;
      }
      let body: { email: string; password: string };
      try {
        body = parseLoginBody(parseJsonRequestBody(request));
      } catch (error) {
        const raw = bestEffortEmail(request.body);
        auth.writeAudit(raw, "FAILURE", "VALIDATION_ERROR", request.ip);
        limits.recordLoginFailure(request.ip);
        throw error;
      }

