import { render, screen, waitFor } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { App } from "./App";
import { ApiClient } from "./api";
import { resetSessionMemoryForTests } from "./session";

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

function futureSession() {
  return {
    token: "bearer-persistido",
    expiresAt: new Date(Date.now() + 3_600_000).toISOString(),
  };
}

function simulatePersistedSession(session = futureSession()) {
  localStorage.setItem("exchange.session.v1", JSON.stringify(session));
  resetSessionMemoryForTests();
}

describe("bootstrap y expiración de sesión", () => {
  it("AT-10-01-09 valida una sesión persistida con GET /me y navega a trading", async () => {
    simulatePersistedSession();
    const fetchMock = vi.spyOn(globalThis, "fetch").mockResolvedValue(jsonResponse({
      accountId: "account-1",
      email: "trader@example.com",
      status: "ACTIVE",
      createdAt: "2026-09-07T00:00:00.000Z",
    }));
    const navigate = vi.fn();

    render(<App apiBaseUrl="http://backend.test/" navigate={navigate} />);

    await waitFor(() => expect(navigate).toHaveBeenCalledWith("/trading"));
    expect(fetchMock).toHaveBeenCalledTimes(1);
    const [url, init] = fetchMock.mock.calls[0];
    expect(url).toBe("http://backend.test/api/v1/me");
    expect(new Headers(init?.headers).get("Authorization")).toBe("Bearer bearer-persistido");
    expect(document.body).not.toHaveTextContent("bearer-persistido");
  });

  it("AT-10-01-10 limpia una sesión revocada y permanece en login", async () => {
    simulatePersistedSession();
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ error: { code: "UNAUTHENTICATED", message: "no confiable" } }, 401),
    );
    const navigate = vi.fn();

    render(<App apiBaseUrl="http://backend.test" navigate={navigate} />);

    expect(await screen.findByRole("heading", { name: "Ingresá a tu cuenta" })).toBeVisible();
    expect(localStorage.getItem("exchange.session.v1")).toBeNull();
    expect(navigate).not.toHaveBeenCalledWith("/trading");
  });

  it("RN-11 descarta una sesión localmente expirada sin llamar al servidor", async () => {
    simulatePersistedSession({ token: "vencido", expiresAt: new Date(Date.now() - 1).toISOString() });
    const fetchMock = vi.spyOn(globalThis, "fetch");

    render(<App apiBaseUrl="http://backend.test" navigate={vi.fn()} />);

    expect(await screen.findByRole("heading", { name: "Ingresá a tu cuenta" })).toBeVisible();
    expect(fetchMock).not.toHaveBeenCalled();
    expect(localStorage.getItem("exchange.session.v1")).toBeNull();
  });

  it("AT-10-01-07 una llamada protegida no autenticada limpia y publica el aviso", async () => {
    simulatePersistedSession();
    const redirect = vi.fn();
    const api = new ApiClient({
      baseUrl: "http://backend.test",
      fetchImpl: vi.fn<typeof fetch>().mockResolvedValue(
        jsonResponse({ error: { code: "UNAUTHENTICATED" } }, 401),
      ),
      onUnauthenticated: () => redirect("/login"),
